const sheets = $json.sheets || [];
const s = sheets.find(x => x.properties.title === "Anna Call Agenda");
const requests = s ? [{deleteSheet:{sheetId: s.properties.sheetId}}] : [];
return [{json:{requests}}];

const sheets = $json.sheets || [];
const s = sheets.find(x => x.properties.title === "Anna Call Agenda");
if (!s) return [{json:{requests:[]}}];
const sid = s.properties.sheetId;
const requests = [];

requests.push({updateSheetProperties:{properties:{sheetId:sid,gridProperties:{frozenRowCount:1}},fields:"gridProperties.frozenRowCount"}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:0,endRowIndex:1},cell:{userEnteredFormat:{backgroundColor:{red:0.12,green:0.16,blue:0.22},horizontalAlignment:"LEFT",verticalAlignment:"MIDDLE",wrapStrategy:"WRAP",textFormat:{foregroundColor:{red:1,green:1,blue:1},bold:true,fontSize:11}}},fields:"userEnteredFormat(backgroundColor,horizontalAlignment,verticalAlignment,wrapStrategy,textFormat)"}});
requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:120},cell:{userEnteredFormat:{verticalAlignment:"TOP",wrapStrategy:"WRAP",textFormat:{fontSize:10}}},fields:"userEnteredFormat(verticalAlignment,wrapStrategy,textFormat)"}});

[135,260,540,80,110,105].forEach((w,i) => {
  requests.push({updateDimensionProperties:{range:{sheetId:sid,dimension:"COLUMNS",startIndex:i,endIndex:i+1},properties:{pixelSize:w},fields:"pixelSize"}});
});

requests.push({repeatCell:{range:{sheetId:sid,startRowIndex:1,endRowIndex:120,startColumnIndex:1,endColumnIndex:2},cell:{userEnteredFormat:{textFormat:{bold:true,fontSize:10}}},fields:"userEnteredFormat.textFormat"}});

const secRule = (txt,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:120,startColumnIndex:0,endColumnIndex:1}],booleanRule:{condition:{type:"TEXT_CONTAINS",values:[{userEnteredValue:txt}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(secRule("1. LOCKED",{red:0.82,green:0.94,blue:0.85},{red:0.04,green:0.35,blue:0.18}));
requests.push(secRule("2. ANNA OWES",{red:1,green:0.95,blue:0.8},{red:0.48,green:0.33,blue:0.02}));
requests.push(secRule("3. WE OWE",{red:1,green:0.87,blue:0.87},{red:0.6,green:0.11,blue:0.11}));
requests.push(secRule("4. DECIDE",{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));
requests.push(secRule("5. STILL TO ASK",{red:0.91,green:0.88,blue:0.99},{red:0.32,green:0.16,blue:0.6}));
requests.push(secRule("6. THINK ABOUT",{red:0.93,green:0.93,blue:0.93},{red:0.3,green:0.3,blue:0.3}));
requests.push(secRule("7. CALL NOTES",{red:0.97,green:0.97,blue:0.97},{red:0.45,green:0.45,blue:0.45}));

const ownerRule = (name,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:120,startColumnIndex:3,endColumnIndex:4}],booleanRule:{condition:{type:"TEXT_EQ",values:[{userEnteredValue:name}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(ownerRule("Krish",{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));
requests.push(ownerRule("Loz",{red:0.99,green:0.89,blue:0.94},{red:0.6,green:0.09,blue:0.33}));
requests.push(ownerRule("Both",{red:0.88,green:0.89,blue:0.99},{red:0.2,green:0.19,blue:0.6}));
requests.push(ownerRule("Anna",{red:1,green:0.95,blue:0.8},{red:0.48,green:0.33,blue:0.02}));

const statusRule = (txt,bg,fg) => ({addConditionalFormatRule:{rule:{ranges:[{sheetId:sid,startRowIndex:1,endRowIndex:120,startColumnIndex:5,endColumnIndex:6}],booleanRule:{condition:{type:"TEXT_CONTAINS",values:[{userEnteredValue:txt}]},format:{backgroundColor:bg,textFormat:{bold:true,foregroundColor:fg}}}},index:0}});
requests.push(statusRule("Locked",{red:0.82,green:0.94,blue:0.85},{red:0.04,green:0.35,blue:0.18}));
requests.push(statusRule("Awaiting",{red:1,green:0.95,blue:0.8},{red:0.48,green:0.33,blue:0.02}));
requests.push(statusRule("Open",{red:1,green:0.87,blue:0.87},{red:0.6,green:0.11,blue:0.11}));
requests.push(statusRule("Opportunity",{red:0.85,green:0.91,blue:0.99},{red:0.06,green:0.27,blue:0.56}));

requests.push({addBanding:{bandedRange:{range:{sheetId:sid,startRowIndex:1,endRowIndex:120,startColumnIndex:0,endColumnIndex:6},rowProperties:{firstBandColor:{red:1,green:1,blue:1},secondBandColor:{red:0.975,green:0.975,blue:0.98}}}}});

requests.push({updateSheetProperties:{properties:{sheetId:sid,index:1},fields:"index"}});

return [{json:{requests}}];
